            return
        if target_x > x:
            dx = 1
        elif target_x < x:
            dx = -1
        else:
            dx = 0
        if target_y > y:
            dy = 1
        elif target_y < y:
            dy = -1
        else:
            dy = 0

    # 1) Try to pursue goal
    if isinstance(goal, (list, tuple)) and len(goal) >= 2:
        gx, gy = goal[0], goal[1]
        move_towards(gx, gy)

    # 2) If no goal, head toward the closest resource if available
