                best = (rx, ry)
        if best is not None:
            move_towards(best[0], best[1])

    # 3) If still no move, avoid enemies by stepping away from nearest
    if dx == 0 and dy == 0 and enemies:
        # find nearest enemy
        nearest = None
        nearest_dist = None
        for e in enemies:
