            if nearest_dist is None or dist < nearest_dist:
                nearest_dist = dist
                nearest = (ex, ey)
        if nearest is not None:
            # move away along axis if possible
            ex, ey = nearest
            dx = -1 if ex > x else (1 if ex < x else 0)
            dy = -1 if ey > y else (1 if ey < y else 0)

    # 4) Fallback: small random-like movement using deterministic pattern (no randomness)
    if dx == 0 and dy == 0:
